        emon.Testport.assertEq(Sealfield.sfDigit(1635), 3, "an Arabic-Indic 3");
        emon.Testport.assertEq(Sealfield.sfDigit(1782), 6, "an Extended Arabic-Indic 6");
        emon.Testport.assertEq(Sealfield.sfDigit(2407), 1, "a Devanagari 1");
        emon.Testport.assertEq(Sealfield.sfDigit(65301), 5, "a fullwidth 5");
        emon.Testport.assertEq(Sealfield.sfDigit(65), -1, "a letter is none");
        emon.Testport.assertEq(Sealfield.sfScript(65), 1, "A is Latin");
        emon.Testport.assertEq(Sealfield.sfScript(233), 1, "so is e acute");
        emon.Testport.assertEq(Sealfield.sfScript(1040), 3, "Cyrillic A");
        emon.Testport.assertEq(Sealfield.sfScript(945), 2, "Greek alpha");
        emon.Testport.assertEq(Sealfield.sfScript(20013), 10, "a Han letter");
